      "default": true
    },
    "retrieveBudgetChars": {
      "type": "number",
      "title": "Retrieval budget (chars)",
      "description": "Most characters of archived content retrieved per prompt (the host caps all hidden context at 32000).",
      "default": 6000
    },
    "snapshot": {
      "type": "boolean",
      "title": "Snapshot before compaction",
      "description": "Write the exact pre-compaction transcript to .lossless-compact/snapshots/ so any removed message can be read back.",
      "default": true
    },
    "noteRemoved": {
      "type": "boolean",
      "title": "Note where the history is",
      "description": "Insert one message into the compacted transcript saying what was removed and where the snapshot, archive and raw session log are.",
      "default": true
    },
    "preserveRecentMessages": {
      "type": "number",
      "title": "Recent messages to preserve",
      "description": "Number of newest messages pinned from compaction.",
      "default": 6
    },
    "compactAtTokens": {
      "type": "number",
      "title": "Compact at (tokens)",
      "description": "Compact once the live context holds this many tokens. A count, not a share of the window. 0 turns it off.",
      "default": 120000
    },
    "compactAtPercent": {
      "type": "number",
      "title": "Compact at (percent of window)",
      "description": "Optional second trigger: compact when context usage reaches this percent of the model window. 0 (default) turns it off.",
      "default": 0
    },
    "minReductionRatio": {
      "type": "number",
      "title": "Minimum reduction ratio",
      "description": "Minimum estimated character reduction required to replace history.",
      "default": 0.25
    },
    "maxStateTokens": {
      "type": "number",
      "title": "Maximum Jev state tokens",
      "description": "Estimated token budget for the conversation state sent with every Jev request.",
      "default": 25000
    },
    "maxRequestTokens": {
      "type": "number",
      "title": "Maximum Jev request tokens",
      "description": "Estimated token budget for state plus questions in one Jev request.",
      "default": 30000
    },
    "truncateHeadChars": {
      "type": "number",
      "title": "Truncated tool result head",
      "description": "Characters of a tool result kept when Jev decides its full output is no longer needed; 0 keeps only the note.",
      "default": 300
    },
    "model": {
      "type": "string",
      "title": "Jev model",
      "description": "TypeSafe Jev model name.",
      "default": "jev-latest"
    }
  }
}
